function easytier_services()
{
    $services = [];

    if (easytier_enabled()) {
        $services[] = [
            'description' => gettext('EasyTier VPN'),
            'configd' => [
                'start' => ['easytier start'],
                'stop' => ['easytier stop'],
                'restart' => ['easytier restart'],
                'configure' => ['easytier reconfigure'],
            ],
            'name' => 'easytier',
            'pidfile' => '/var/run/easytier.pid',
        ];
    }

    return $services;
}

function easytier_configure()
{
    return [
        'bootup' => ['easytier_configure_do:0'],
    ];
}

function easytier_configure_do()
{
    if (easytier_enabled()) {
        mwexecf('/usr/local/bin/configctl easytier reconfigure');
    }
}

